package com.practiq.common;
public class ApiException extends RuntimeException { public final int status; public final String code; public final Object details; public ApiException(int status,String code,String message){this(status,code,message,null);} public ApiException(int status,String code,String message,Object details){super(message);this.status=status;this.code=code;this.details=details;} public static ApiException of(int s,String c,String m){return new ApiException(s,c,m);} public static ApiException of(int s,String c,String m,Object details){return new ApiException(s,c,m,details);} }
